/*------------------------------------------------------------------
Hey there! This card layout is a fork of Pranav Deshai's Prettify Card Layout.
His repo: https://github.com/pranavdeshai/anki-prettify
Buy him a coffee at: https://www.buymeacoffee.com/pranavdeshai
If you liked my take on his theme you can buy me a coffee here:
https://www.buymeacoffee.com/anubisnekhet
------------------------------------------------------------------*/
/* -------------------------------------------------- PREFERENCES */
/* -------------------------------------------------- COLOR PREFS */
:root {
  --card-max-width: 40em;
  --card-text-align: left;
  --font-size-regular: 16px;
  --font-size-small: 14px;
  --img-width: 50%;
  --img-brightness: 0.95;
  --img-filter: none;
  --font-weight: 600;
  --table-radius: 0.8em;
  --card-radius: 8px;
  --mochi-toggle: block;
}

.mobile {
  --card-max-width: 40em;
  --card-text-align: left;
  --font-size-regular: 16px;
  --font-size-small: 14px;
  --img-width: 50%;
  --img-brightness: 0.95;
  --img-filter: none;
  --font-weight: 600;
  --table-radius: 0.8em;
  --card-radius: 8px;
  --mochi-mobile-toggle: block;
}

/* -------------------------------------------------- COLORS */
.card.card.night_mode {
  background-color: #242426;
  --text-fg: #ffffffe6;
  --text-fg-faint: #ffffffb3;
  --text-bg-selected: #ffffff1f;
  --card-bg: #2e2f31;
  --card-border: #ffffff0a;
  --card-box-shadow: #0000001f;
  --divider: #ffffff1f;
  --tag-fg: #ffffffb3;
  --tag-bg: #ffffff14;
  --tag-fg-active: #ffffff;
  --tag-bg-active: #ffffff1f;
}

/*--------------------------------------------------- THEME VARS */
.card {
  --text-fg: #4C4F69;
  --text-fg-faint: #6C6F85;
  --text-bg-selected: #BCC0CC;
  --card-border: #BCC0CC;
  --card-box-shadow: #0000001f;
  --divider: #BCC0CC;
  --tag-fg: #5C5F77;
  --tag-bg: #9CA0B0;
  --tag-fg-active: #DE9584;
  --tag-bg-active: #ACB0BE;
  --tag-border: transparent;
  --cloze-fg: #E49320;
  --cloze-bg: #EFF1F5;
  --link-fg: #2A6EF5;
  --link-bg: transparent;
  --link-fg-active: #04A5E5;
  --link-bg-active: transparent;
  --bold-fg: #E49320;
  --italic-fg: #40A02B;
  --h1-fg: #40A02B;
  --h2-fg: #179299;
  --h3-fg: #8839EF;
  --h4-fg: #D20F39;
  --h5-fg: #04A5E5;
  --bold-italic-fg: var(--bold-fg);
  --highlight1: #E64553;
  --highlight2: #40A02B;
  --highlight3: #7287FD;
  --highlight4: #FE640B;
  --scheme-rosewater: #DE9584;
  --scheme-flamingo: #DD7878;
  --scheme-pink: #EC83D0;
  --scheme-mauve: #8839EF;
  --scheme-red: #D20F39;
  --scheme-maroon: #E64553;
  --scheme-peach: #FE640B;
  --scheme-yellow: #E49320;
  --scheme-green: #40A02B;
  --scheme-teal: #179299;
  --scheme-sky: #04A5E5;
  --scheme-sapphire: #209FB5;
  --scheme-blue: #2A6EF5;
  --scheme-lavender: #7287FD;
  --scheme-crust: #DCE0E8;
  --scheme-grey: #6C6F85;
  --mark-color: rgba(228, 147, 32, 0.2);
  --callout-base: var(--ctp-yellow);
  --ctp-rosewater: 222,
  	149,
  	132;
  --ctp-flamingo: 221,
  	120,
  	120;
  --ctp-pink: 236,
  	131,
  	208;
  --ctp-mauve: 136,
  	57,
  	239;
  --ctp-red: 210,
  	15,
  	57;
  --ctp-maroon: 230,
  	69,
  	83;
  --ctp-peach: 254,
  	100,
  	11;
  --ctp-yellow: 228,
  	147,
  	32;
  --ctp-green: 64,
  	160,
  	43;
  --ctp-teal: 23,
