/*------------------------------------- BUTTONS */
button,
.isMac button {
  color: var(--tag-fg);
  color: var(--text-fg);
  border-radius: 0.2em;
  box-shadow: none;
  border: 1px solid var(--card-border);
  border-bottom-color: var(--card-border);
  font-size: var(--font-size-small);
  font-family: inherit;
  transition: all 0.25s;
  background: none;
  background-color: var(--tag-bg);
}
button:active, button:hover,
.isMac button:active,
.isMac button:hover {
  background: none;
  background-color: var(--tag-bg-active);
  color: var(--tag-fg-active);
  cursor: pointer;
}

/*------------------------------------- SCROLLBARS */
::-webkit-scrollbar {
  width: 11px;
  background-color: transparent;
}

::-webkit-scrollbar:horizontal {
  height: 11px;
}

::-webkit-scrollbar-corner {
  background-color: transparent;
}

::-webkit-scrollbar-track {
  background-color: transparent;
}

::-webkit-scrollbar-thumb {
  background-clip: padding-box;
  border-radius: 20px;
  border: 3px solid transparent;
  background-color: rgba(var(--ctp-text), 0.1);
  border-width: 3px 3px 3px 3px;
  min-height: 45px;
}

::-webkit-scrollbar-thumb:hover {
  background-color: rgba(var(--ctp-text), 0.2);
}

::-webkit-scrollbar-thumb:active {
  background-color: rgba(var(--ctp-text), 0.3);
}

/*--------------------------------------------------- ADDITIONS */
/*--------------------------IMAGE OCCLUSION---------------------------*/
#io-overlay img,
#io-original img {
  transition: none !important;
  width: 100% !important;
  opacity: 1;
  max-width: 100% !important;
  max-height: 100% !important;
  border-radius: 0;
  margin: 0;
}

#io-overlay img:hover,
#io-original img:hover {
  cursor: unset;
  filter: none;
  max-width: 100%;
  max-height: 100%;
  opacity: 1;
}

html:not(.mobile) #io-overlay img:active,
html:not(.mobile) #io-original img:active {
  border: none;
  cursor: unset;
  filter: none;
  left: unset;
  max-width: 100% !important;
  max-height: 100% !important;
  opacity: 1;
  position: inherit;
  top: unset;
  transform: none;
  z-index: inherit;
}

*::selection {
  background-color: var(--card-bg);
}

/* OCCLUSION CSS START - don't edit this */
#io-overlay {
  position: absolute;
  top: 0;
  width: 100%;
  z-index: 3;
}

#io-original {
  position: relative;
  top: 0;
  width: 100%;
  z-index: 2;
  visibility: hidden;
}

#io-wrapper {
  position: relative;
  width: 100%;
  height: 100%;
}

/* OCCLUSION CSS END */
/* OTHER STYLES */
#io-header {
  font-size: 1.1em;
  margin-bottom: 0.2em;
}

#io-footer {
  max-width: 80%;
  margin-left: auto;
  margin-right: auto;
  margin-top: 0.8em;
  font-style: italic;
}

#io-extra-wrapper {
  /* the wrapper is needed to center the
   left-aligned blocks below it */
  width: 80%;
  margin-left: auto;
  margin-right: auto;
  margin-top: 0.5em;
}

#io-extra {
  text-align: center;
  display: inline-block;
}

.io-extra-entry {
  margin-top: 0.8em;
  font-size: 0.9em;
  text-align: left;
}

.io-field-descr {
  margin-bottom: 0.2em;
  font-weight: bold;
  font-size: 1em;
}

/* ADJUSTMENTS FOR MOBILE DEVICES */
.mobile .card,
.mobile #content {
  font-size: 120%;
  margin: 0;
}

.mobile #io-extra-wrapper {
  width: 95%;
}

.mobile #io-revl-btn {
  font-size: 0.8em;
}

.mobile #io-wrapper,
.mobile .io-wrapper {
  max-width: 90%;
  max-height: 90%;
  margin: auto;
}

/* -------------------------------------------------- IMAGES */
img.zoomable-image,
.zoomable-image img,
.extra img {
  border-radius: 0.25em;
  display: block;
  margin: 1em auto;
  max-width: var(--img-width) !important;
  transition: max-width 0.25s 0.1s, opacity 0.25s 0.1s, filter 0.1s, transform 0s;
}

.night_mode img.zoomable-image,
.night_mode .zoomable-image img,
.night_mode .extra img {
  filter: var(--img-filter);
  opacity: var(--img-brightness);
}

img.zoomable-image:hover,
.zoomable-image img:hover,
.extra img:hover {
  cursor: zoom-in;
  filter: none;
  max-width: 100% !important;
  opacity: 1;
}

img.zoomable-image + br,
.zoomable-image img + br,
.extra img + br {
  display: none;
}

html:not(.mobile) img.zoomable-image:active,
html:not(.mobile) .zoomable-image img:active,
html:not(.mobile) .extra img:active {
  border: 1px solid var(--link-fg-active);
  cursor: zoom-out;
  filter: none;
  left: 0;
  max-width: 95% !important;
  opacity: 1;
  position: fixed;
  top: 0;
  transform: translate(calc(50vw - 50%), calc(50vh - 50%));
  z-index: 100;
}

.prettify-species {
  color: var(--scheme-green);
  font-style: italic;
}

[tag=S_Aureus] {
  --tag-fg: rgb(var(--ctp-red));
  --tag-bg: rgba(var(--ctp-red), 0.2);
}

[tag=Entamoeba_Histolytica] {
  --tag-fg: rgb(var(--ctp-green));
  --tag-bg: rgba(var(--ctp-green), 0.2);
}

[tag=Hepatitis],
[tag=Hepatitis_A],
[tag=Hepatitis_B],
[tag=Hepatitis_C],
[tag=Hepatitis_D],
[tag=Hepatitis_E],
[tag=Neisseria_gonorrhoeae] {
  --tag-fg: rgb(var(--ctp-teal));
  --tag-bg: rgba(var(--ctp-teal), 0.2);
}

[tag=Neisseria_meningitidis] {
  --tag-fg: rgb(var(--ctp-blue));
  --tag-bg: rgba(var(--ctp-blue), 0.2);
}

.cloze.cloze-inactive {
  color: var(--scheme-red);
}

.prettify-tags {
  display: block;
}

/* -------------------------------------------------- FONTS */
@font-face {
  font-family: "Carlito";
  src: url(_Carlito-Regular.ttf);
  font-style: normal;
  font-weight: 400;
}
@font-face {
  font-family: "Carlito";
  src: url(_Carlito-Italic.ttf);
  font-style: italic;
  font-weight: 400;
}
@font-face {
  font-family: "Carlito";
  src: url(_Carlito-Bold.ttf);
  font-style: normal;
  font-weight: 700;
}
@font-face {
  font-family: "Carlito";
  src: url(_Carlito-BoldItalic.ttf);
  font-style: italic;
  font-weight: 700;
}
/*---------------------------------- SELECT FONTS */
:root {
  --font-family: "Carlito";
}

.mobile {
  --font-family: "Carlito";
}

#FlipFront, #FlipBack {
	 transition: 0.5s cubic-bezier(.15, .5, .3, 1.3);
    transform-style: preserve-3d;
    backface-visibility: hidden;
}
#FlipBack, #FlipFront.flipped {
transform: rotateX(180deg);
}
#FlipFront, #FlipBack.flipped {
transform: rotateX(0deg);
}

